raw_response:
{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= k <= n <= 10^5",
      "description": "The number of main courses and the total number of courses are within the specified bounds."
    },
    {
      "id": "P2",
      "expression": "1 <= t_i <= n",
      "description": "Each course dependency list contains valid course numbers."
    },
    {
      "id": "P3",
      "expression": "The sum of all t_i does not exceed 10^5",
      "description": "The total number of dependencies does not exceed the specified limit."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "output == -1",
      "description": "The output is -1 if there is no way to get a specialty."
    },
    {
      "id": "Q2",
      "expression": "output == m",
      "description": "The output m is the minimum number of courses to pass to get a specialty."
    },
    {
      "id": "Q3",
      "expression": "output == course_order",
      "description": "The output course_order is the order of courses to pass in chronological order."
    }
  ],
  "invariants": [
    {
      "id": "I1",
      "expression": "all(course in course_order for course in main_courses)",
      "description": "All main courses are included in the course order."
    },
    {
      "id": "I2",
      "expression": "all(course in course_order for course in necessary_courses)",
      "description": "All necessary courses are included in the course order."
    },
    {
      "id": "I3",
      "expression": "len(course_order) == m",
      "description": "The length of the course order is equal to the minimum number of courses to pass."
    },
    {
      "id": "I4",
      "expression": "all(course_order[i] < course_order[i+1] for i in range(m-1))",
      "description": "The course order is in chronological order."
    }
  ]
}
